script:
// Independent public HTML/AMP reader. No app endpoints, challenge solver or page eval.
var BASE='https://cn.webmota.com';
function fail(s){throw new Error('包子漫画+：'+s);}
function absolute(s){if(!s)return '';if(s.indexOf('//')===0)return 'https:'+s;if(s[0]==='/')return BASE+s;return s;}
function own(url){return /^https:\/\/(?:cn\.|www\.)?webmota\.com\//.test(url);}
async function html(url){if(!own(url))fail('无效的来源地址');var r=await triomi.fetch(url,{headers:{Referer:BASE+'/'}});if(r.status!==200)fail('HTTP '+r.status);if(/Just a moment|cf-chl-|challenge-platform|captcha|人机验证/i.test(r.body))fail('站点要求验证；不自动绕过');return r.body;}
async function value(body,selector,attr){var a=await triomi.select(body,selector,{v:{selector:'.',attr:attr||'text'}});return a.length?String(a[0].v||'').trim():'';}
async function list(url){var body=await html(url);var rows=await triomi.select(body,'.comics-card',{title:'.comics-card__title',url:{selector:'a.comics-card__poster',attr:'href'},coverUrl:{selector:'a.comics-card__poster > amp-img',attr:'src'},author:'.comics-card__info small'});var seen={},result=[];rows.forEach(function(x){var m=(x.url||'').match(/^\/comic\/([A-Za-z0-9_-]+)\/?$/);if(!m||!x.title||seen[m[1]])return;seen[m[1]]=true;result.push({remoteId:m[1],title:x.title,url:BASE+'/comic/'+m[1],coverUrl:absolute(x.coverUrl),author:x.author});});return result;}
async function discover(url,page){return list(BASE+'/classify?page='+page);}
async function search(q,page){if(page>1)return [];return list(BASE+'/search?q='+encodeURIComponent(q));}
async function detail(url,snapshot){
 var slug=(url.match(/\/comic\/([A-Za-z0-9_-]+)\/?(?:[?#].*)?$/)||[])[1]||snapshot.remoteId;if(!/^[A-Za-z0-9_-]+$/.test(slug||''))fail('漫画标识无效');
 var body=await html(BASE+'/comic/'+slug),canonical=await value(body,'meta[name="og:novel:read_url"]','content');var canon=(canonical.match(/\/comic\/([A-Za-z0-9_-]+)/)||[])[1];if(canon)slug=canon;
 var rows=await triomi.select(body,'a.comics-chapters__item',{title:{selector:'.'},url:{selector:'.',attr:'href'}}),seen={},chapters=[];
 rows.forEach(function(x){var q=x.url||'',section=(q.match(/[?&]section_slot=(\d+)/)||[])[1],slot=(q.match(/[?&]chapter_slot=(\d+)/)||[])[1];if(section==null||slot==null||!x.title)fail('章节目录格式无效');var key=section+'_'+slot;if(seen[key])return;seen[key]=true;chapters.push({remoteId:slug+'/'+key,title:x.title,url:BASE+'/comic/chapter/'+slug+'/'+key+'.html',volumeTitle:'分组 '+(Number(section)+1),section:Number(section),slot:Number(slot),locked:false});});
 chapters.sort(function(a,b){return a.section-b.section||a.slot-b.slot;});if(!chapters.length)fail('公开目录为空或作品已下架');
 var title=await value(body,'meta[name="og:novel:book_name"]','content');if(!title)fail('漫画详情缺少标题');
 var status=await value(body,'meta[name="og:novel:status"]','content');
 return {item:{remoteId:slug,title:title,url:BASE+'/comic/'+slug,coverUrl:await value(body,'.comics-detail amp-img','src'),author:await value(body,'meta[name="og:novel:author"]','content'),description:await value(body,'.comics-detail__desc'),status:/完结|完結/.test(status)?'completed':'ongoing'},chapters:chapters};
}
function chapterKey(url){var m=url.match(/\/comic\/chapter\/([A-Za-z0-9_-]+)\/(\d+)_(\d+)(?:_(\d+))?\.html(?:[?#].*)?$/);if(!m)fail('章节地址格式无效');return {section:m[2],slot:m[3],page:Number(m[4]||1)};}
async function content(url,chapter){
 var original=chapterKey(url),current=url,seenPages={},seenImages={},images=[];
 for(var step=0;step<200;step++){
  if(seenPages[current])fail('阅读分页形成循环');seenPages[current]=true;var body=await html(current);
  var rows=await triomi.select(body,'.comic-contain__item',{url:{selector:'.',attr:'data-src'},src:{selector:'.',attr:'src'}});if(!rows.length)fail('公开章节没有图片或需要 APP/登录');
  rows.forEach(function(x){var image=absolute(x.url||x.src);if(!/^https:\/\/(?:[a-z0-9-]+\.)?(?:bzcdn\.net|baozicdn\.com|baozimh\.com)\//.test(image)||/[\s\\]/.test(image))fail('图片地址无效');if(!seenImages[image]){seenImages[image]=true;images.push(image);}});
  var nextText=await value(body,'#next-chapter'),next=await value(body,'#next-chapter','href');
  if(!/下一页|下一頁/.test(nextText))return {images:images,headers:{Referer:BASE+'/'}};
  next=absolute(next);if(!own(next))fail('阅读分页跳转到其他来源');var now=chapterKey(current),key=chapterKey(next);
  if(key.section!==original.section||key.slot!==original.slot||key.page!==now.page+1)fail('阅读分页越过当前章节或不连续');current=next;
 }
 fail('章节分页过多，拒绝返回不完整章节');
}
